async function prepare(mode,auto=false){if(busy||blocked||w.GakuAuto?.busy)return;const id=uid();busy=true;preview=null;message='Memeriksa cadangan akun…';changed();try{guard(id);const local=capture(),{s,db}=await connection(id),ref=s.doc(db,'users',id,'study','snapshot'),remote=w.GakuDelta?await w.GakuDelta.load(id).catch(e=>{if(e.message.startsWith('Belum ada cadangan'))return null;throw e;}):unpack(await s.getDocFromServer(ref));guard(id);if(mode==='download'&&!remote)throw Error('Belum ada cadangan di akun ini. Gunakan Simpan ke akun dari perangkat yang memiliki data.');preview={id,mode,local,remote,ref,s,db,auto};message='';}catch(e){message=error(e);}finally{busy=false;changed();}}
async function confirm(){if(busy||!preview||w.GakuAuto?.busy)return;busy=true;const p=preview;message='Memproses…';changed();try{guard(p.id);if(JSON.stringify(capture())!==JSON.stringify(p.local))throw Error('Data HP berubah sejak pratinjau. Periksa cadangan lagi.');if(p.mode==='upload'){let deltaResult;if(w.GakuDelta)deltaResult=await w.GakuDelta.publish(p.id,p.local,p.remote);else await p.s.runTransaction(p.db,async tx=>{guard(p.id);const current=unpack(await tx.get(p.ref));if((current?.revision||0)!==(p.remote?.revision||0))throw Error('Cadangan akun berubah dari perangkat lain. Periksa ulang sebelum menyimpan.');guard(p.id);tx.set(p.ref,{version:1,revision:(current?.revision||0)+1,payload:JSON.stringify(p.local),updatedAt:p.s.serverTimestamp()});});guard(p.id);w.GakuAuto?.accepted(p.id,deltaResult?.epoch||((p.remote?.revision||0)+1),p.local,p.auto,deltaResult?.seq||0);message='Data HP berhasil disimpan ke akun. Jika otomatis aktif di perangkat lain, pembaruan diperiksa saat aplikasinya terbuka.';}else{const now=w.GakuDelta?await w.GakuDelta.verify(p.id,p.remote):unpack(await p.s.getDocFromServer(p.ref));guard(p.id);if(now?.revision!==p.remote.revision||(now?.sequence||0)!==(p.remote.sequence||0))throw Error('Cadangan akun berubah. Periksa ulang sebelum mengambil.');if(JSON.stringify(capture())!==JSON.stringify(p.local))throw Error('Data HP berubah. Periksa ulang.');restore(now.values);w.GakuAuto?.accepted(p.id,now.revision,now.values,p.auto,now.sequence||0);preview=null;w.location.reload();return;}preview=null;}catch(e){preview=null;message=error(e);}finally{busy=false;changed();}}
function cancel(){if(busy)return;preview=null;message='';changed();}
function downloadBackup(previous=false){try{const data=previous==='account'?(preview?.remote?{version:1,createdAt:new Date().toISOString(),values:preview.remote.values}:null):previous?JSON.parse(w.localStorage.getItem(BACKUP)||'null'):{version:1,createdAt:new Date().toISOString(),values:capture()};if(!data)throw Error('Belum ada cadangan sebelum pemulihan.');validate(data.values);const url=URL.createObjectURL(new Blob([JSON.stringify({format:'dex-gaku-study-backup',...data},null,2)],{type:'application/json'})),a=w.document.createElement('a');a.href=url;a.download='dex-gaku-cadangan-'+Date.now()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message='Cadangan diunduh. Simpan file sebelum mengganti data.';}catch(e){message=error(e);}changed();}
function panel(){if(preview&&preview.id!==uid()){preview=null;message='Akun berubah. Silakan periksa cadangan lagi.';}if(!uid())return '';if(w.GakuAuto?.isAutomatic)return w.GakuAuto.panel();const p=preview;return `<section class="account-card" aria-label="Sinkronisasi belajar" aria-busy="${busy}"><h3>Sinkronisasi akun</h3><p class="hint">Perubahan belajar disimpan otomatis saat online. Tidak perlu menekan tombol kirim.</p>${w.GakuAuto?.panel()||''}<details ${p||w.GakuAuto?.needsReview?'open':''} style="margin-top:16px"><summary style="cursor:pointer;font-weight:600">Cadangan &amp; pengaturan</summary><div style="margin:16px 0">${w.GakuAuto?.controls?.()||''}</div><div style="display:flex;flex-wrap:wrap;gap:10px"><button class="google-button" onclick="GakuCloud.prepare('upload')" ${busy?'disabled':''}>Simpan ke akun ↑</button><button class="google-button" onclick="GakuCloud.prepare('download')" ${busy?'disabled':''}>Ambil dari akun ↓</button><button class="chip" onclick="GakuCloud.downloadBackup()" ${busy?'disabled':''}>Unduh cadangan HP</button><button class="chip" onclick="GakuCloud.downloadBackup(true)" ${busy?'disabled':''}>Unduh data sebelum pemulihan</button></div>${p?`<div style="margin-top:20px;padding:18px;border:1px solid currentColor;border-radius:18px"><h3>${p.mode==='upload'?'Simpan data HP ini?':'Gunakan data dari akun?'}</h3><p>Akun: ${esc(w.GakuAuth.user.email||'Google')}</p><p>HP ini: ${esc(counts(p.local))}</p><p>Akun: ${p.remote?esc(counts(p.remote.values))+'<br>'+esc(p.remote.date):'Belum ada cadangan'}</p><p>${p.mode==='upload'?'Cadangan akun sebelumnya akan diganti dengan seluruh data HP ini. Unduh cadangan akun melalui perangkat yang memakainya jika masih diperlukan.':'Seluruh data belajar HP akan diganti dengan cadangan akun. Data HP sebelumnya dicadangkan di perangkat ini. Setelah selesai, halaman dimuat ulang.'} Data tidak digabungkan. ${p.auto?'Setelah berhasil, sinkronisasi otomatis aktif untuk akun ini di HP ini.':''}</p>${p.remote?`<button class="chip" onclick="GakuCloud.downloadBackup('account')" ${busy?'disabled':''}>Unduh cadangan akun ini</button>`:''}<button class="google-button" onclick="GakuCloud.confirm()" ${busy?'disabled':''}>${p.mode==='upload'?'Ya, simpan ke akun':'Ya, ambil dan muat ulang'}</button> <button class="chip" onclick="GakuCloud.cancel()" ${busy?'disabled':''}>Batal</button></div>`:''}<p role="status" aria-live="polite">${esc(message)}</p></details></section>`;}
recover();
w.GakuCloud={applyLive(values){restore(values);w.GakuCloud.onApplied?.(values);},KEYS,validate,capture,restore,recover,prepare,confirm,cancel,panel,downloadBackup,get busy(){return busy;},get reviewing(){return !!preview;},get recoveryBlocked(){return blocked;}};
w.addEventListener('load',()=>{if(blocked){const overlay=w.document.createElement('div');overlay.setAttribute('role','alert');overlay.style.cssText='position:fixed;inset:0;z-index:2147483647;background:#fff;color:#243c32;padding:32px;overflow:auto';overlay.innerHTML='<h2>Pulihkan penyimpanan dahulu</h2><p>Data belajar belum bisa dipulihkan. Kosongkan ruang penyimpanan perangkat, lalu tekan tombol di bawah. Jangan hapus data situs.</p><button onclick="location.reload()">Coba pulihkan</button>';w.document.body.appendChild(overlay);}});
